// Function to capture the image
async function captureImage() {
  // Get access to the camera
  const mediaDevices = await navigator.mediaDevices.getUserMedia({ video: true });

  // Access the media stream
  const video = mediaDevices.getVideoStream();

  // Create a canvas for the image
  const canvas = document.createElement('canvas');
  const ctx = canvas.getContext('2d');

  // Draw a frame to the canvas
  canvas.width = 640;
  canvas.height = 480;
  ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
  const imageData = canvas.toDataURL();

  // Optionally do something with the image data
  console.log("Image captured:", imageData);

  // Optional: Send the image data or clear the canvas
  // ...

  // Clean up after taking the picture
  video.getTracks().forEach(track => track.stop());
}


