import os

def delete_files(directory, delete_option="ALL"):
  """
  Permanently deletes files in a directory.

  Args:
    directory: The directory to delete files from.
    delete_option:  Specifies how to handle files. 
                   - 'ALL': Deletes all files.
                   - 'TRASH': Deletes files marked as trash (if your file system supports that).
  """

  if delete_option == "ALL":
    try:
      for item in os.listdir(directory):
        full_path = os.path.join(directory, item)
        if os.path.isfile(full_path):
          os.remove(full_path)
          print(f"Deleted file: {full_path}")
    except Exception as e:
      print(f"Error deleting files in {directory}: {e}")
  elif delete_option == "TRASH":
    try:
      for item in os.listdir(directory):
        full_path = os.path.join(directory, item)
        if os.path.isfile(full_path):
          if not os.path.isfile(os.path.join(directory, f"{item}.trash")):
            os.rename(full_path, f"{full_path}.trash")
            print(f"File moved to trash: {full_path}")
  else:
    print("Invalid delete option. Choose 'ALL' or 'TRASH'.")

# Example usage:
delete_files("/path/to/your/files")  # Replace with the actual path
```


